const { sign } = require('./sign');
const deadLetters = require('./dead-letters');

async function deliverOnce(transport, sub, body) {
  const headers = { 'content-type': 'application/json', 'x-signature': sign(sub.secret, body) };
  try {
    await transport.post(sub.url, body, headers);
    return { id: sub.id, ok: true };
  } catch (err) {
    deadLetters.record(sub.id, err.message);
    return { id: sub.id, ok: false };
  }
}

async function deliverAll(transport, subs, event) {
  const body = JSON.stringify(event);
  const results = [];
  for (const sub of subs) results.push(await deliverOnce(transport, sub, body));
  return results;
}

module.exports = { deliverAll };
class HttpTransport {
  constructor(fetchImpl, metrics) {
    this.fetch = fetchImpl;
    this.metrics = metrics;
  }

  async post(url, body, headers) {
    const res = await this.fetch(url, { method: 'POST', body, headers });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    return res;
  }
}

module.exports = { HttpTransport };

